import type { Reading } from './store.ts';

export interface DayReport {
  date: string; // YYYY-MM-DD
  validSecs: number;
  anomalySecs: number;
  unknownSecs: number;
  /** 当日估算消耗(毫千瓦时);无有效覆盖时为 null。 */
  milli: bigint | null;
