    const dayEnd = Math.min((d + 1) * DAY, to);
    let valid = 0, anomaly = 0;
    let milli = 0n;
    let hasValid = false;
    for (const iv of ivs) {
      if (iv.end <= dayStart) continue;
      if (iv.start >= dayEnd) break;
      const s = Math.max(iv.start, dayStart);
      const e = Math.min(iv.end, dayEnd);
      const secs = e - s;
      if (!iv.valid) { anomaly += secs; continue; }
      valid += secs;
      hasValid = true;
      const dur = iv.end - iv.start;
      const cum = (t: number) => (iv.diff * BigInt(t - iv.start)) / BigInt(dur); // floor for non-negative
      milli += cum(e) - cum(s);
    }
    const unknown = (dayEnd - dayStart) - valid - anomaly;
    if (anomaly > 0 || unknown > 0) complete = false;
    days.push({ date: dateOf(d), validSecs: valid, anomalySecs: anomaly, unknownSecs: unknown, milli: hasValid ? milli : null });
    if (hasValid) total = (total ?? 0n) + milli;
  }
  return { device, days, totalMilli: total, complete };
}
```

